import { CommonModule } from '@angular/common';
import { ChangeDetectorRef, Component, NgZone } from '@angular/core';
import { InputComponent } from '../../../../shared/components/input/input.component';
import { TextareaComponent } from '../../../../shared/components/textarea/textarea.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { CaseBuilderService } from '../../../services/case-builder/case-builder.service';
import { ActivatedRoute, Router } from '@angular/router';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { HeaderService } from '../../../../core/services/header/header.service';
import { Subscription } from 'rxjs';
import { CommunicationService } from '../../../../shared/services/communication/communication.service';
import { CaseResponce } from '../../../interfaces/casebuilder.interface';
import { SkeletonComponent } from '../../../../shared/components/skeleton/skeleton.component';
import { ContentEditableComponent } from '../../../../shared/components/content-editable/content-editable.component';
import { UserPermissionService } from '../../../../shared/services/user-permission/user-permission.service';

@Component({
  selector: 'app-casecreation',
  standalone: true,
  imports: [
    CommonModule,
    InputComponent,
    TextareaComponent,
    ButtonComponent,
    ReactiveFormsModule,
    IconComponent,
    ContentEditableComponent
  ],
  templateUrl: './casecreation.component.html',
  styleUrl: './casecreation.component.scss'
})
export class CasecreationComponent {
  caseForm: FormGroup;
  showinput: boolean = false;
  isLoading: boolean = false;
  getYear: any = new Date().getFullYear();
  nCaseid: string;
  private evsubscription: Subscription;
  constructor(private formBuilder: FormBuilder, private caseS: CaseBuilderService, private router: Router,
    private route: ActivatedRoute, private cf: CommonfunctionService, private hs: HeaderService, private cdr: ChangeDetectorRef, private cs: CommunicationService,
    private userPermissions: UserPermissionService
  ) {
    this.checkEventSub();
  }

  async checkEventSub() {
    this.evsubscription = this.cs.functionCalled$.subscribe(async (data) => {
      if (data == 'DELETE-CASE') {
        let rs = await this.caseS.caseDelete(this.nCaseid);
        if (rs) {
          this.cf.goto('/admin/dashboard');
        }
      } else if (data == 'VIEW-TICKETS') {
        this.cf.goto('/admin/tickets', { id: this.nCaseid })
      }
    })
  }

  ngOnInit() {
    var params = this.route.snapshot.params;
    params = JSON.parse(atob(params["id"]));
    this.nCaseid = params && params["id"] ? params["id"] : 0;

    this.userPermissions.userPermissionList(this.nCaseid);

    this.caseForm = this.formBuilder.group({
      nCaseid: [0],
      cCasename: ['', [Validators.required]],
      cCaseno: ['', [Validators.required]],
      cDesc: ['', [Validators.required]],
      cIndexheader: [''],
      cClaimant: [''],
      cRespondent: [''],
      cTClaimant: [''],
      cTRespondent: [''],
      permission: [this.nCaseid ? 'E' : 'N', [Validators.required]]
    });

  }

  async getCaseDetail(nCaseid) {
    let res: any = await this.caseS.getCaseDetail(nCaseid);
    this.hs.Casedetail = res;
    this.caseForm.patchValue({
      nCaseid: res.nCaseid,
      cCasename: res.cCasename,
      cCaseno: res.cCaseno,
      cDesc: res.cDesc,
      cIndexheader: res.cIndexheader,
      cClaimant: res.cClaimant,
      cRespondent: res.cRespondent,
      cTClaimant: res.cTClaimant ? res.cTClaimant : '',
      cTRespondent: res.cTRespondent ? res.cTRespondent : '',
      permission: 'E'
    })
  }
  ngAfterViewInit(): void {
    this.hs.updatePath('case detail');
    if (this.nCaseid) {
      this.hs.updateisCase(true);
      this.getCaseDetail(this.nCaseid)
    } else {
      this.hs.updateisCase(false);
    }
    this.cdr.detectChanges();
  }

  ngOnDestroy() {
    this.evsubscription.unsubscribe();
  }

  async onSubmit() {
    this.isLoading = true;
    if (this.caseForm.valid) {
      let res: CaseResponce = await this.caseS.caseBuilder(this.caseForm.value);
      this.isLoading = false;
      if (res.msg == 1) {
        var params = { id: res.nCaseid };
        this.replaceCurrentUrlWithNewUrl(params)
      }
    }
  }


  replaceCurrentUrlWithNewUrl(params) {
    var url: any = btoa(JSON.stringify(params));
    this.router.navigate(['/casebuilder/casecreation', url], { replaceUrl: true });
    setTimeout(() => {
      this.cf.goto('/casebuilder/teamsetup', params);
    }, 20);
  }

  goToteam() {
    this.cf.goto('/casebuilder/teamsetup', { id: this.nCaseid });
  }
  focusOut(ev) {
    console.log(ev);
    if (ev == 'out')
      this.showinput = false;
  }

}
